```java
CompletableFuture<Void> bouncer = CompletableFuture.runAsync(() -> {
    try (Admin admin = cluster.admin()) {
        while (bouncing.get()) {
            for (int brokerId : cluster.brokerIds()) {
                cluster.shutdownBroker(brokerId);
                cluster.brokers().get(brokerId).awaitShutdown();
                TimeUnit.MILLISECONDS.sleep(500);
                cluster.startBroker(brokerId);
                TimeUnit.MILLISECONDS.sleep(500);
            }
            for (int partition = 0; partition < NUM_PARTITIONS; partition++) {
                TopicPartition tp = new TopicPartition(OUTPUT_TOPIC, partition);
                TestUtils.waitForCondition(() -> hasLeader(admin, tp), "No leader elected for " + tp);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Broker bouncer failed", e);
    }
});
